def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_defects = 0
    my_defects = 0
    recent_opp_defects = 0
    recent_my_defects = 0
    all_opp_c = True
    all_opp_d = True
    D_to_C = 0
    D_to_D = 0

    recent_start = n - 10
    if recent_start < 0:
        recent_start = 0

    for i in range(n):
        me, opp = history[i]

        if me == 'D':
            my_defects += 1
        if opp == 'D':
            opp_defects += 1
            all_opp_c = False
        else:
            all_opp_d = False

        if i >= recent_start:
            if me == 'D':
                recent_my_defects += 1
            if opp == 'D':
                recent_opp_defects += 1

        if i > 0 and history[i - 1][0] == 'D':
            if opp == 'C':
                D_to_C += 1
            else:
                D_to_D += 1

    my_last, opp_last = history[-1]

    if all_opp_d:
        return 'D'

    if all_opp_c:
        if my_defects == 0:
            if n < 30:
                return 'C'
            return 'D'
        if my_last == 'D':
            if my_defects == 1:
                return 'C'
            return 'D'
        return 'D'

    if opp_defects * 3 > n * 2 or recent_opp_defects >= 6:
        return 'D'

    if my_defects == 0 and n >= 35 and recent_opp_defects == 0 and opp_defects <= 2:
        return 'D'

    if opp_last == 'C':
        if (
            D_to_C > D_to_D + 4
            and recent_opp_defects <= 1
            and recent_my_defects <= 9
            and opp_defects * 5 <= n * 4
        ):
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            if D_to_C >= D_to_D and opp_defects * 5 <= n * 4:
                if recent_opp_defects <= 1 or recent_my_defects <= 8:
                    return 'D'

        return 'C'

    caused = False
    caused_start = n - 5
    if caused_start < 0:
        caused_start = 0

    for j in range(caused_start, n):
        if history[j][0] == 'D':
            caused = True
            break

    if caused and recent_opp_defects <= 4 and opp_defects * 3 <= n * 2:
        return 'C'

    if my_last == 'D':
        if opp_defects * 2 <= n and recent_opp_defects <= 3:
            return 'C'
        return 'D'

    return 'D'
